-- Descricao propria para as 70 pecas da loja que estavam sem texto.
-- Escritas a partir da foto e do cadastro de cada peca, em 16/11/2026.
-- So preenche o que esta vazio: nao sobrescreve descricao escrita depois.

update products as p set description = v.descricao
from (values
  ('094b1c72-c71c-4ce6-913f-484f78cda679'::uuid, 'Blazer curto em vermelho vinho, com gola xale e dois botões dourados na frente. O corte acinturado e a manga longa deixam a peça elegante sobre vestido, blusa estampada ou calça de alfaiataria.'),  -- 01 BLAZER 6073 TATIANA
  ('587498d8-934a-4a19-b6ef-d4e3b815480e'::uuid, 'Blazer curto vermelho de gola xale, com um botão na frente e punho fechado por botão forrado. O comprimento acima do quadril valoriza a cintura e combina com saia lápis, calça social ou jeans.'),  -- 02 BLAZER 6077 DEODORA
  ('9f95eecd-ee55-4899-9bfb-03117782cc38'::uuid, 'Blazer rosa de corte transpassado, com duas fileiras de botões dourados e bolsos com lapela. Ombro estruturado e cintura marcada: é a peça que transforma um look simples em produção de evento.'),  -- 03 Blazer 6917 Karina
  ('0362553f-060f-4c85-b9cd-5d53236212f5'::uuid, 'Blazer curto amarelo de manga três quartos, leve e sem forro pesado. A cor abre o look sobre branco, off white ou azul marinho, e o comprimento curto alonga a silhueta.'),  -- 04 BLAZER AMELIA
  ('a303a5af-08f2-43ad-9607-27b68a7b00b3'::uuid, 'Blazer cor telha com cordão de amarração na cintura, bolsos frontais e botõezinhos no punho. Tecido macio, de cair solto: o tipo de peça que se usa o dia inteiro sem apertar.'),  -- 05 BLAZER AURORA
  ('115779ed-cb15-4f66-bd44-2ac182d1227b'::uuid, 'Blazer de gola xale e corte curto acinturado, com bolso na frente e fechamento de um botão. Acompanha bem vestido floral, saia midi ou calça preta.'),  -- 06 Blazer Rebeca
  ('043cf154-a7c7-4b2b-9098-f2c718e27afc'::uuid, 'Blusa off white em laise, com furinhos bordados no próprio tecido e manga curta ampla, de caimento solto. Gola redonda e corpo leve: boa para o calor e fácil de combinar com saia de qualquer cor.'),  -- 07 Blusa 6261 carmen
  ('b20b6600-abbf-437d-a445-ed7d19597785'::uuid, 'Blusa verde de manga longa bufante com punho, fechada por um laço gravata na gola. O verde puxa para o oliva e combina com bege, caramelo e jeans.'),  -- 08 Blusa 6894 Lidia
  ('8433d523-7725-4af3-a39f-aa8d48b7109b'::uuid, 'Blusa off white com estampa floral em tons de rosa no centro e manga transparente de poás. Delicada: pede saia lisa, para deixar a estampa em primeiro plano.'),  -- 09 Blusa 7037 Eloa
  ('67e76d6a-abce-479f-a0c4-60bdf4dc2eb6'::uuid, 'Blusa de tule vermelho com estampa de arabescos, gola alta e manga longa. O franzido no centro da frente marca a cintura. Peça de festa que também funciona no trabalho, sob um blazer.'),  -- 10 Blusa 7094 Simaria
  ('f4f6d414-7fac-49bb-96ab-43dda21c0fd6'::uuid, 'Camiseta de malha com gola redonda, manga curta e bordado pequeno no peito. Básica de verdade: entra embaixo de blazer, por dentro da saia ou sozinha no fim de semana.'),  -- 11 Blusa adele
  ('cea4540e-ce5a-4f7e-875d-d854e1f745e0'::uuid, 'Blusa curta em renda azul clara, com manga curta de babado duplo e botõezinhos dourados no decote. Corpo forrado. Fica bonita por dentro de saia de cintura alta.'),  -- 12 Blusa Curta na Renda Bordada Silvia
  ('deeedab1-85f1-48e4-a797-f2cdeae4508d'::uuid, 'Peça vermelha de manga curta, com acabamento em xadrez vichy na gola e no punho e cinto de fivela marcando a cintura. Tecido firme, de cair reto até a barra longa.'),  -- 13 Blusa deise
  ('defe9229-7b3d-47e4-ad5f-a549ea6e8e2f'::uuid, 'Blusa coral de malha, com manga curta e amarração na cintura. Cor viva, que ilumina o rosto e combina com jeans, branco e bege.'),  -- 14 Blusa lúcia
  ('d538b837-9815-48b0-8ca4-e2cee10a2be7'::uuid, 'Azul marinho de malha, com decote V fechado por zíper curto, manga curta e cordão na cintura. Confortável para o dia todo e discreto o bastante para trabalhar.'),  -- 15 Blusa pilar
  ('5dc69954-9f9b-4565-942f-4b70ff56c0e5'::uuid, 'Blusa de malha com renda na barra da manga, caimento solto e gola redonda. O detalhe de renda é o que tira a peça do básico.'),  -- 16 Blusa roberta
  ('72b683ff-f01b-4671-acd0-c56f7f2d7f7e'::uuid, 'Blusa vermelha em tule estampado de arabescos, com gola alta, manga longa e franzido no centro da frente. Transparência leve: pede um top por baixo.'),  -- 17 BLUSA SIMARIA
  ('031679ea-de27-4058-863c-ebf859d397f3'::uuid, 'Camisa vermelha de manga longa, com renda aplicada no ombro, botões perolados e punho bufante. Uma das poucas peças da loja com a grade inteira, do PP ao GG.'),  -- 18 Camisa 6792 Luciana
  ('e6b04c7d-c682-4b66-8573-ba5838c16178'::uuid, 'Camisa social vermelha com renda no ombro, botões perolados e manga bufante de punho largo. Fecha até em cima e vai de reunião a jantar.'),  -- 19 Camisa com Renda e Botões Luciana
  ('979b12bf-afe0-4a80-816f-2a8a2e800423'::uuid, 'Camisa verde de estampa marmorizada, com manga longa de punho elástico e botões na frente. Comprimento curto, para usar por dentro de saia de cintura alta.'),  -- 20 Camisa Curta no Pied de Poule Adriely
  ('da6376a4-dcaf-4866-9947-7ee25e3a34a3'::uuid, 'Sobretudo azul serenity de comprimento midi, com gola de alfaiataria, botões forrados e bolsos embutidos. Tecido encorpado (92% poliéster, 5% viscose e 3% elastano) e forro interno: peça de inverno, para usar sobre vestido ou calça.'),  -- 21 CASACO MAX
  ('686386c8-daea-4092-a3de-ceff9132a76f'::uuid, 'Jaqueta jeans claro de corte curto, com bolsos no peito e botões metálicos. A peça que resolve o fim de tarde sobre vestido, saia ou macacão.'),  -- 22 Jaqueta 7660 Jeans Monica
  ('77e200fc-ef4c-4cf7-b518-61f93eb68c31'::uuid, 'Jaqueta curta em linho cru com bolinhas coloridas bordadas, manga três quartos e botões na frente. Leve, para usar sobre blusa branca ou top de malha.'),  -- 23 Jaqueta Feminina Linho Bordado Botões Clarice
  ('d46613da-ca5d-4c1e-957c-ed81da15adb2'::uuid, 'Conjunto de duas peças em vermelho coral: blusa de manga curta com babado no ombro e saia midi evasê com botões na frente. Combina junto e funciona separado.'),  -- 24 CONJUNTO
  ('7da3c96f-6c66-43a3-95ca-14af4d19ed71'::uuid, 'Conjunto azul claro em tweed de malha: casaqueto acinturado de manga longa e saia midi com fenda e detalhe frontal. Composição de 94% algodão, 4% viscose e 2% elastano — a estrutura do tweed com o conforto da malha.'),  -- 25 CONJUNTO EM TWEEW DE MALHA
  ('3a843b28-b5a3-43e1-9720-f4ab0281573e'::uuid, 'Conjunto caramelo em malha canelada: blusa de gola polo com manga curta e saia midi lápis com cordão na cintura. Monocromático, alonga a silhueta inteira.'),  -- 26 CONJUNTO FEMININE
  ('93f8f806-8015-46dc-995f-91999b664f1c'::uuid, 'Conjunto de camisa off white com laço no punho e saia midi preta evasê, em couro ecológico. Contraste clássico, pronto para um jantar ou um culto.'),  -- 27 CONJUNTO FEMININE
  ('bd67a626-ccab-4d72-ab1e-2a0f333b8118'::uuid, 'Conjunto rosa em malha: blusa de gola polo com manga curta e saia midi transpassada, com botão dourado na lateral. Confortável como malha, arrumado como alfaiataria.'),  -- 28 Conjunto helena
  ('1d1e77ea-bae2-440f-90b7-c717bf6970fa'::uuid, 'Conjunto em alfaiataria twill: casaqueto curto de manga longa com botões funcionais e bolsos, e saia lápis com zíper. Corte estruturado, para quem quer o look inteiro resolvido numa peça só.'),  -- 29 CONJUNTO LIANA
  ('8d83053f-de00-443c-ad3e-5911eade94ee'::uuid, 'Conjunto de blusa off white com zíper no decote e saia vermelha em couro ecológico, com babado na barra e zíperes nos bolsos. Vermelho com off white, combinação que não erra.'),  -- 30 CONJUNTO MAYA
  ('b52cc7e2-87c2-4171-877d-3fb103726bb4'::uuid, 'Conjunto verde em tecido leve: camisa de manga curta com botões e saia midi evasê com cordão na cintura e fenda lateral. Verde vivo, feito para o calor.'),  -- 31 CONJUNTO TATI
  ('8b9440fc-8f8f-4bb8-88b9-4634169d8338'::uuid, 'Conjunto em tweed mescla mascavo: blazer acinturado com quatro bolsos e saia reta com botões na frente. Composição 100% poliéster. O lenço que aparece na foto não acompanha a peça.'),  -- 32 CONJUNTO TWEED
  ('8b7ac714-3da2-44b1-9f39-a24696668b18'::uuid, 'Saia lápis midi verde em malha firme, de cintura alta e caimento justo. Combina com branco, off white, preto e caramelo.'),  -- 33 SAIA
  ('671736b8-4233-4805-9183-db77f1bf19f5'::uuid, 'Saia longa bordô em sarja, com cinto de fivela, bolsos com passante e pesponto branco aparente. Rodada na barra, confortável de andar.'),  -- 34 SAIA AGATHA
  ('6dee0746-c722-44d3-bad3-cba22ce66843'::uuid, 'Saia preta lápis de comprimento midi, cintura alta e caimento reto. A base que combina com qualquer blusa do armário.'),  -- 35 SAIA ANTONELLA
  ('85f7f58a-6f58-4e6b-a64d-e55b603e942a'::uuid, 'Saia midi caramelo em couro ecológico, com recortes e barra godê, que abre no movimento. O caramelo cai bem com preto, marrom e off white.'),  -- 36 SAIA BIANCA
  ('f48ed6ca-b860-46b0-9373-10879315d06e'::uuid, 'Saia lápis preta em couro ecológico, de cintura alta com botões dourados na frente. Caimento firme, que modela a silhueta.'),  -- 37 SAIA COURO ECOLOGICO
  ('05d098bf-2abd-4394-939a-d6ddff9d3315'::uuid, 'Saia midi lápis com botões forrados na frente e cintura alta. Corte limpo, sem bolso aparente: fica bem com a blusa por dentro.'),  -- 38 SAIA ELIZA
  ('cff0c960-cc08-4c9e-a402-86fb0c146323'::uuid, 'Saia preta midi de cintura alta, com botõezinhos na frente e fenda na barra. Tecido de alfaiataria, caimento reto.'),  -- 39 SAIA JULIA
  ('d089a85a-d2e6-469d-a2e0-a2f49260df4b'::uuid, 'Saia jeans midi com recortes verticais que abrem a barra em godê, bolsos e botão metálico na cintura. Jeans que serve para o trabalho.'),  -- 40 SAIA MIDI
  ('886f11e1-eb0d-40bf-9f29-0c5c704c07bf'::uuid, 'Saia lápis midi verde escuro, com cós largo, acabamento desfiado na cintura e pingente metálico. Verde profundo, fácil de combinar com off white e bege.'),  -- 41 SAIA RETA
  ('f226c28c-18b3-4ced-bf1f-259c9f21d356'::uuid, 'Saia lápis de cós alto e largo, fechamento de zíper e caimento justo até o joelho. Clássica de escritório, cadastrada em três cores.'),  -- 42 SAIA SECR C/ZIPER ROSANE
  ('441b3c5e-d175-473b-89ef-fcad9c0079bd'::uuid, 'Saia lápis de estampa geométrica em tons terrosos, entre o verde, o bordô e o bege. Cós alto e caimento reto. Resolve o look com uma blusa lisa, preta ou branca.'),  -- 43 SAIA SECRETARIA
  ('5d8bd22a-a543-4c0e-9fda-641da2447048'::uuid, 'Saia em couro ecológico com zíper metálico aparente de ponta a ponta na frente, cós alto e bolsos com lapela. Comprimento no joelho.'),  -- 44 SAIA TAINARA
  ('5c68620e-ca51-4dad-8d35-4ef7d31339bd'::uuid, 'Vestido chemise midi azul marinho, com gola de camisa, manga longa de punho e faixa de amarração na cintura. Saia evasê com fenda. Elegante sem ser formal demais.'),  -- 45 VESTIDO
  ('b38e38f1-c5fd-4efd-8901-75fdc21cab89'::uuid, 'Vestido midi rosa com poás brancos, manga curta e saia evasê. Franzido no ombro e cintura marcada: o vestido de almoço de domingo.'),  -- 46 Vestido 5712 marilza
  ('0fd3e8d4-6895-4322-be74-4b83e41e144d'::uuid, 'Vestido midi branco em laise bordada, com decote quadrado, manga curta bufante e saia em três camadas de babado, com barra em bico. Para casamento civil, chá de casa nova ou formatura.'),  -- 47 VESTIDO AMELIA
  ('6b166cdf-e34a-451d-8ed5-0ec250c6e11e'::uuid, 'Vestido midi em renda, com manga curta ampla, franzido no corpo e barra godê. O franzido no tecido disfarça e valoriza ao mesmo tempo.'),  -- 48 VESTIDO ANA CLARA
  ('3aa2ca54-650a-4e03-b0b7-e0c3c5b86c41'::uuid, 'Vestido longo rosa pink com decote quadrado, manga curta bufante e saia ampla com fenda. Tecido leve, que balança no movimento.'),  -- 49 VESTIDO CARMEM
  ('5dfff702-2375-428e-8df1-a0ce817f9766'::uuid, 'Vestido chemise midi com botões de cima a baixo, manga curta e cordões que franzem a lateral da cintura. Decote V e bolsos embutidos.'),  -- 50 VESTIDO CHEMISE
  ('87204646-4485-45c1-94d2-1fea82d6631d'::uuid, 'Vestido de paetê rosa pink, tubinho de manga curta e comprimento no joelho. Brilho por toda a peça: é o vestido de réveillon, de formatura, de festa.'),  -- 51 VESTIDO DENISE
  ('cd749b05-1276-4fdd-8c74-7b8e20138aef'::uuid, 'Vestido midi em tricô canelado, com gola alta rolê e manga longa, de caimento justo. Quente e confortável para os dias frios. Cadastrado em preto, verde e terracota.'),  -- 52 Vestido eva
  ('29175205-05a0-4cb6-a9c9-9fc01d104f6d'::uuid, 'Vestido midi preto em malha, com manga longa morcego, franzido lateral preso por broche dourado e fenda na frente. Peça de jantar.'),  -- 53 VESTIDO FEMININE
  ('7c00a3a7-ddae-4318-b7c8-6ac91fbe1f35'::uuid, 'Vestido midi canelado em tom nude, tubinho de manga curta e gola redonda. Simples e justo: fica bonito com um colar e um salto.'),  -- 54 VESTIDO FEMININE
  ('4447ea2f-3275-42d7-8330-8b79eb53ff17'::uuid, 'Vestido marsala com decote quadrado de acabamento ondulado, manga curta bufante e saia godê rodada, no joelho. Cintura marcada por um babadinho.'),  -- 55 VESTIDO GODE
  ('ae8925c0-6550-4a41-996b-a9174087f321'::uuid, 'Vestido azul petróleo com decote quadrado, manga curta, botões dourados na frente e bolsos com lapela. Saia com pregas, que abrem no movimento.'),  -- 56 VESTIDO GODE
  ('a4279561-1f23-4444-879e-8573c5fdcb43'::uuid, 'Vestido longo chemise listrado em verde e branco, com barra estampada de paisagem tropical. Manga curta com dobra, botões de cima a baixo e bolsos. Tecido leve, de verão.'),  -- 57 VESTIDO KATIA
  ('a9f254ca-3f46-4485-aa9d-b38dc6913904'::uuid, 'Vestido longo cru com decote ombro a ombro de elástico, manga curta bufante e cintura franzida. Bordado floral azul na barra, com babado. Vestido de passeio.'),  -- 58 VESTIDO LISA
  ('2bc9d97b-b286-40d3-a0bd-23f48f4478ba'::uuid, 'Vestido preto em voil de poás, com renda no decote e mangas de tule transparente. Chiffon poá, 100% poliéster. Para festa à noite.'),  -- 59 VESTIDO LONGO MIDI
  ('da07ad46-d9ab-4d0f-858a-e4a1908f74f6'::uuid, 'Vestido midi azul jeans em malha, com manga longa, botões forrados no peito, cinto fino e bolsos com lapela. Caimento justo e acabamento de alfaiataria.'),  -- 60 VESTIDO MARIA CLARA
  ('4bb22ee4-f135-4885-9b09-e18c9b08d675'::uuid, 'Vestido longo cinza chumbo mesclado, com decote V de cordão, cava ampla e cordão na cintura. Babado na barra. Malha leve, de cair solto no corpo.'),  -- 61 VESTIDO MAX MIDI
  ('3b790987-02a5-4598-a168-a0003492de68'::uuid, 'Vestido preto midi com decote quadrado e laço, manga bufante com entremeio vazado e barra em babado. Detalhes de renda no corpo e na cintura.'),  -- 62 VESTIDO MIDI
  ('6f213834-2f1f-4468-b4f4-fb7e810dabfc'::uuid, 'Vestido chemise midi off white em tecido leve, com pequenos bordados dourados, manga longa bufante, botões e faixa de amarração na cintura. Saia evasê. A peça mais sofisticada da loja.'),  -- 63 VESTIDO MIDI MEIRE
  ('08c66a26-c1b6-4d3a-8515-05f4325ff176'::uuid, 'Vestido midi de estampa quadriculada em tons de laranja e off white, com laço na gola, manga curta e saia em camadas de babado. Tecido leve e rodado.'),  -- 64 Vestido milena
  ('afb3545d-6499-43bc-87e0-7347c7cbe54c'::uuid, 'Vestido tubinho preto com recortes em off white na frente e bordado de pedraria na gola, manga longa e comprimento no joelho. Veste o corpo e dispensa colar.'),  -- 65 VESTIDO MONIQUE
  ('d4367f23-7241-41ca-8eb1-c1eec7921a3c'::uuid, 'Vestido longo off white com poás verdes em crepe de toque de seda, estampa exclusiva. Decote V, manga curta com laço e babado na barra. Composição de 92% poliéster e 8% elastano.'),  -- 66 VESTIDO RAQUEL
  ('40a0cdf1-f9a4-4491-8fb3-28fb552d5ae6'::uuid, 'Vestido longo rosa chemise, com gola de camisa, manga curta, botões de cima a baixo e cinto de fivela. Saia muito rodada a partir do quadril.'),  -- 67 VESTIDO ROSE
  ('5d05dee8-2df2-46c8-b021-8c4dba27ba6b'::uuid, 'Vestido midi roxo com manga curta franzida no ombro, botõezinhos no peito e saia evasê com pregas e bolsos. Roxo fechado, cor pouco vista por aí.'),  -- 68 VESTIDO SIRRAH
  ('5b7f60c7-e74d-4396-9380-e156ffb46e12'::uuid, 'Vestido vermelho de malha, tubinho de manga curta e gola redonda, no comprimento do joelho. Básico de cor forte: resolve o dia com uma rasteira e a noite com salto.'),  -- 69 Vestido thais
  ('f5b7e7e6-765e-4171-83d7-df3ba925502c'::uuid, 'Vestido tubinho preto com duas listras brancas no peito e no ombro, manga curta e bolsos embutidos. Esportivo e justo, para o dia a dia.')  -- 70 VESTIDO TUBINHO C/ BOLSOS
) as v(id, descricao)
where p.id = v.id
  and (p.description is null or btrim(p.description) = '');
